"""Derive operation budgets from exact offline censuses and archived A7 controls."""
from pathlib import Path
from hashlib import sha256
import json,sys
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'build/partial-selective-private-v1'
def main(archive):
 archive=archive.resolve();assert archive.is_relative_to(ROOT/'device-evidence')
 prof=json.loads((ROOT/'build/partial-merge-private-v1/analysis.json').read_text());pre=json.loads((ROOT/'build/partial-preflight-private-v1/analysis.json').read_text());prior=json.loads((archive/'fullpaths-analysis/analysis.json').read_text());asm=json.loads((OUT/'assembly-summary.json').read_text());cases=[]
 for c in prof['cases']:
  t=c['totals'];p=next(x for x in pre['cases'] if x['case']==c['case'])['totals'];hist=c['mask_shapes'];n1=sum(m['rows_per_call'] for m in hist if m['mode']==0 and int(m['mask_hex'],16).bit_count()==1);n2=sum(m['rows_per_call'] for m in hist if m['mode']==0 and int(m['mask_hex'],16).bit_count()==2);checks=sum(b['partial_rows'] for b in c['buckets'] if b['mode']==0);plain=sum(b['active_rows'] for b in c['buckets'] if b['mode']==0)
  old=[x for x in prior['matched_comparisons'] if x.get('fixture')==c['case'] and x.get('variant')=='combined'];assert len(old)==2 and all(x['aligned_interval_complete'] for x in old);gap=[-x['mean_deadline_margin_us'] for x in old];target=[-x['mean_20_percent_margin_us'] for x in old]
  row={'case':c['case'],'name':c['name'],'partial_rows':t['partial_rows'],'plain_partial_rows':checks,'plain_active_rows':plain,'sparse_one_pixel_rows':n1,'sparse_two_pixel_rows':n2,'eligible_sparse_rows':n1+n2,'eligible_fraction_of_partial_rows':(n1+n2)/t['partial_rows'],'terminal_logical_byte_reduction':34*n1+28*n2,'terminal_byte_model':'Original partial store path reads16 RGB bytes and writes16 RGB+8 depth. Sparse path adds n index-byte and2n palette-byte reads and writes2n RGB+n depth. Difference40-6n bytes; initial index/depth loads, cache-line traffic, guards/spills and fallback effects excluded. Not DRAM bandwidth.','rows_with_unchanged_active_RGB':t['partial_RGB_write_noop'],'depth_store_noop_rows':t['partial_depth_write_noop'],'direct_full_depth_legal_rows':t['partial_direct_depth_legal'],'full_half_only_rows':t['partial_single_full_half'],'depth4_probe':{k:v for k,v in p.items() if k.startswith('depth4_')},'scorecard':f'S_us = L + {n1}*s1 + {n2}*s2 - {checks}*q - B; all prices unmeasured','blind_depth4_scorecard':f"S4_us = {p['depth4_hidden_tiles']}*h - {p['depth4_probe_row_visits']}*p - B4; prices unmeasured, not implemented",'prior_combined_conservative_deadline_gap_us':gap,'prior_combined_conservative_20_percent_gap_us':target,'current_combined_gain_G_us':'PENDING_RETURN; subtract G before pricing any remaining deficit','sparse_credit_only_scenarios':[{'net_hit_credit_us':u,'saving_before_all_guard_and_other_costs_us':(n1+n2)*u} for u in (.05,.1,.2,.25,.3,.5)],'optimistic_per_hit_threshold_before_G_L_guards_for_old_deadline_us':[v/(n1+n2) for v in gap],'optimistic_per_hit_threshold_before_G_L_guards_for_old_20_percent_us':[v/(n1+n2) for v in target]};cases.append(row)
 result={'status':'OFFLINE_QUALIFIED_NOT_INSTALLED','A7_savings_measured':False,'QEMU_timings_used':False,'card_access':False,'frameskip':False,'production_gate_passed':False,'cases':cases,'assembly':asm,'proofs':{'profile_calls':3600,'preflight_probe_calls':3600,'prototype_calls':7200,'selective_calls':3600,'total_original_output_calls':18000,'scalar_tile_cases':387072,'canonical_mask_cases':32768,'scalar_reference_reused_by_hash':True},'limits':['Counts identify applicability, not microsecond costs.','Current physical combined1 remains unchanged; its logs have not returned.','L is whole non-sparse net saving; s1/s2 are sparse hit credits excluding common guard; q is density guard cost per plain partial row; B includes all other added branches/cache/spills/interactions.','Prior service proxy can double-count overlap and is not a hardware lower bound.','RGB equality cannot justify skipping required depth updates.','Replays compare graphics/PCM every call and normalized state checkpoints every30 calls.','Three contexts and finite independent oracles do not establish universal acceptance.']}
 (OUT/'workback.json').write_text(json.dumps(result,indent=2)+'\n');print('Derived work counts, logical byte model, conditional break-even and retained evidence limits; no A7 timing')
if __name__=='__main__':main(Path(sys.argv[1]))
